from pysat.solvers import Glucose4
from pysat.card import CardEnc, EncType
import time

W = 7
G = 8
P = 32
S = 4

def var(w, g, p):
    return w * G * P + g * P + p + 1

solver = Glucose4()

# Each golfer in exactly one group per week
for w in range(W):
    for p in range(P):
        vars = [var(w, g, p) for g in range(G)]
        solver.add_clause(vars)
        for i in range(G):
            for j in range(i + 1, G):
                solver.add_clause([-vars[i], -vars[j]])

# Each group has exactly S golfers
for w in range(W):
    for g in range(G):
        vars = [var(w, g, p) for p in range(P)]
        cnf = CardEnc.equals(lits=vars, bound=S, encoding=EncType.seqcounter, top_id=solver.nof_vars())
        for clause in cnf.clauses:
            solver.add_clause(clause)

# No two golfers in the same group more than once
for p1 in range(P):
    for p2 in range(p1 + 1, P):
        # They can be in the same group at most once
        # So we can't have (w1, g1) and (w2, g2) where they are together
        # Let together(w, p1, p2) be true if they are in the same group in week w
        # Actually, we can just say: for any w1 < w2, and any g1, g2:
        # not (var(w1, g1, p1) and var(w1, g1, p2) and var(w2, g2, p1) and var(w2, g2, p2))
        # This is O(P^2 * W^2 * G^2) clauses, which is 32^2 * 7^2 * 8^2 / 2 = 1024 * 49 * 64 / 2 = 1.6 million clauses.
        # A bit large. Let's introduce a variable together(w, p1, p2)
        pass

# Let's use the together variables
top = solver.nof_vars()
def tog_var(w, p1, p2):
    # p1 < p2
    idx = p1 * P - p1 * (p1 + 1) // 2 + (p2 - p1 - 1)
    return top + w * (P * (P - 1) // 2) + idx + 1

for w in range(W):
    for p1 in range(P):
        for p2 in range(p1 + 1, P):
            tv = tog_var(w, p1, p2)
            # tv is true iff they are in the same group
            # tv <-> OR_g (var(w, g, p1) AND var(w, g, p2))
            # tv -> OR_g ...
            # not tv or var(w, 0, p1) and var(w, 0, p2) ...
            # Actually, we only need: if they are in the same group, tv is true
            for g in range(G):
                solver.add_clause([-var(w, g, p1), -var(w, g, p2), tv])

for p1 in range(P):
    for p2 in range(p1 + 1, P):
        tvs = [tog_var(w, p1, p2) for w in range(W)]
        # At most 1 tv is true
        for i in range(W):
            for j in range(i + 1, W):
                solver.add_clause([-tvs[i], -tvs[j]])

# Symmetry breaking
# Week 0
for g in range(G):
    for i in range(S):
        solver.add_clause([var(0, g, g * S + i)])

# Week 1
for g in range(G):
    solver.add_clause([var(1, g, g)])

print("Solving...")
t0 = time.time()
res = solver.solve()
print("Solved in", time.time() - t0)
print("Result:", res)

from pysat.solvers import Glucose4
from pysat.card import CardEnc, EncType
import time

W = 7
G = 8
P = 32
S = 4

def var(w, g, p):
    return w * G * P + g * P + p + 1

solver = Glucose4()

# Each golfer in exactly one group per week
for w in range(W):
    for p in range(P):
        vars = [var(w, g, p) for g in range(G)]
        solver.add_clause(vars)
        for i in range(G):
            for j in range(i + 1, G):
                solver.add_clause([-vars[i], -vars[j]])

# Each group has exactly S golfers
for w in range(W):
    for g in range(G):
        vars = [var(w, g, p) for p in range(P)]
        cnf = CardEnc.equals(lits=vars, bound=S, encoding=EncType.seqcounter, top_id=solver.nof_vars())
        for clause in cnf.clauses:
            solver.add_clause(clause)

top = solver.nof_vars()
def tog_var(w, p1, p2):
    idx = p1 * P - p1 * (p1 + 1) // 2 + (p2 - p1 - 1)
    return top + w * (P * (P - 1) // 2) + idx + 1

for w in range(W):
    for p1 in range(P):
        for p2 in range(p1 + 1, P):
            tv = tog_var(w, p1, p2)
            for g in range(G):
                solver.add_clause([-var(w, g, p1), -var(w, g, p2), tv])

for p1 in range(P):
    for p2 in range(p1 + 1, P):
        tvs = [tog_var(w, p1, p2) for w in range(W)]
        for i in range(W):
            for j in range(i + 1, W):
                solver.add_clause([-tvs[i], -tvs[j]])

# Symmetry breaking
# Week 0
for g in range(G):
    for i in range(S):
        solver.add_clause([var(0, g, g * S + i)])

# Week 1
for g in range(G):
    solver.add_clause([var(1, g, g)])

res = solver.solve()
if res:
    model = solver.get_model()
    ans = []
    for w in range(W):
        for p in range(P):
            for g in range(G):
                if model[var(w, g, p) - 1] > 0:
                    ans.append(g)
                    break
